  console.log('\nSession:', sid.slice(0, 12) + '...');
  console.log('  Events:', sessEvents.length);
  console.log('  Types:', JSON.stringify(types));
  console.log('  First:', sessEvents[0]?.type, sessEvents[0]?.timestamp);
  console.log('  Last:', sessEvents[sessEvents.length-1]?.type, sessEvents[sessEvents.length-1]?.timestamp);
});
