node -e "
const data = require('./backend/events.json');
const events = data.events || [];

// Look at sessions that started at SAME TIME (within 2 seconds)
const sessionStarts = events
  .filter(e => e.type === 'SessionStart')
  .map(e => ({ sessionId: e.sessionId, timestamp: e.timestamp, cwd: e.cwd }))
  .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

console.log('=== SessionStart events (sorted by time) ===');
sessionStarts.forEach((s, i) => {
  console.log(\`\${i+1}. \${s.timestamp} | \${s.sessionId?.slice(0,12)}... | cwd: \${s.cwd || 'null'}\`);
});

console.log('\n=== Looking for PAIRS (started within 2 seconds) ===');
for (let i = 0; i < sessionStarts.length - 1; i++) {
  const diff = new Date(sessionStarts[i+1].timestamp) - new Date(sessionStarts[i].timestamp);
  if (diff < 2000) {
    console.log(\`PAIR FOUND! diff=\${diff}ms\`);
    console.log(\`  A: \${sessionStarts[i].sessionId?.slice(0,12)}... at \${sessionStarts[i].timestamp}\`);
    console.log(\`  B: \${sessionStarts[i+1].sessionId?.slice(0,12)}... at \${sessionStarts[i+1].timestamp}\`);

    // Show what happened to each session
    const aEvents = events.filter(e => e.sessionId === sessionStarts[i].sessionId);
    const bEvents = events.filter(e => e.sessionId === sessionStarts[i+1].sessionId);
    console.log(\`  A events: \${aEvents.length} (\${[...new Set(aEvents.map(e => e.type))].join(', ')})\`);
    console.log(\`  B events: \${bEvents.length} (\${[...new Set(bEvents.map(e => e.type))].join(', ')})\`);
  }
}
