// Check if ghost transcript files actually exist
const fs = require('fs');
const pairs = [
  { real: 'b6f673bf-0d35-46ea-979b-08e308b861a8', ghost: '1e23178b-978f-4503-a722-e08fcc68477c' },
  { real: 'a63b1d0b-05a5-45ea-adc3-e4102b3230f8', ghost: '5fb88ee1-9766-4601-b31c-bb004d3896fe' },
  { real: '3e3e4665-f826-4a0c-864c-f7397a340d80', ghost: 'b6425d94-8b4a-4606-83fb-ba6334931f16' }
];

const dir = 'C:/Users/ake9x/.claude/projects/d--Antigravity-Oh-My-Claude';
console.log('=== Transcript file existence check ===');
pairs.forEach((p, i) => {
  const realPath = dir + '/' + p.real + '.jsonl';
  const ghostPath = dir + '/' + p.ghost + '.jsonl';
  const realExists = fs.existsSync(realPath);
  const ghostExists = fs.existsSync(ghostPath);
  const realSize = realExists ? fs.statSync(realPath).size : 0;
  const ghostSize = ghostExists ? fs.statSync(ghostPath).size : 0;
  console.log('Pair ' + (i+1) + ':');
  console.log('  Real:  ' + p.real.slice(0,12) + '  exists=' + realExists + '  size=' + realSize);
  console.log('  Ghost: ' + p.ghost.slice(0,12) + '  exists=' + ghostExists + '  size=' + ghostSize);

  // If ghost exists, show first few lines
  if (ghostExists && ghostSize > 0) {
    const content = fs.readFileSync(ghostPath, 'utf-8');
    const lines = content.trim().split('\\n');
    console.log('  Ghost lines: ' + lines.length);
    if (lines.length > 0) {
      try {
        const first = JSON.parse(lines[0]);
        console.log('  Ghost first entry type: ' + first.type);
      } catch {}
    }
  }
});
