// --- Ghost session filtering ---
// VSCode Extension creates ephemeral "warmup" sessions alongside real ones.
// These ghosts fire SessionStart → Stop → SessionEnd with no real activity.
// Strategy: defer ALL events until real activity is detected.
const REAL_ACTIVITY_EVENTS = new Set([
  'UserPromptSubmit', 'PreToolUse', 'PostToolUse', 'PostToolUseFailure',
  'PreCompact', 'PermissionRequest', 'SubagentStart', 'SubagentStop'
]);

if (event.type === 'SessionStart' && event.sessionId) {
  pendingSessions.set(event.sessionId, { timestamp: event.timestamp, cwd: event.cwd });
  saveEvents();
  return;
}

// Events from pending sessions (no agent yet) — only promote on real activity
if (event.sessionId && pendingSessions.has(event.sessionId) && !agents.has(`main_${event.sessionId}`)) {
  if (REAL_ACTIVITY_EVENTS.has(event.type)) {
    // Real activity — will proceed to create agent below (pending consumed in creation block)
  } else {
    // Not real activity (Stop, SessionEnd, Notification) — keep deferring
    if (event.type === 'SessionEnd') {
      pendingSessions.delete(event.sessionId);
      console.log(`[AGENT] Ghost session discarded: ${event.sessionId.slice(0, 8)}...`);
    }
    saveEvents();
    return;
  }
}

