      const html = hotelBookingCancellationTemplate({
        hotelName: 'Test Hotel',
        bookingNumber: 'BK-003',
        customerName: 'Jane',
        serviceName: 'Massage',
        bookingDate: '2026-02-20',
        bookingTime: '10:00',
        cancellationReason: 'Test',
      })

      expect(html).not.toContain('Room Number')
    })
  })

  describe('staffJobCancellationTemplate', () => {
    it('should generate staff cancellation notice in Thai', () => {
      const html = staffJobCancellationTemplate({
        staffName: 'สมหญิง',
        bookingNumber: 'BK-001',
        serviceName: 'นวดไทย',
        bookingDate: '20 ก.พ. 2569',
